import requests
for pmid in ['27501780','27742828']:
 r=requests.get(f'https://www.ebi.ac.uk/europepmc/webservices/rest/{pmid}/fullTextXML',timeout=20)
 print('\nPMID',pmid,'full text status',r.status_code)
 if r.status_code==200:
  import xml.etree.ElementTree as ET
  root=ET.fromstring(r.text)
  for e in root.iter('abstract'):
   print(' '.join(''.join(e.itertext()).split())[:5000])
 else:
  d=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':f'EXT_ID:{pmid}','format':'json','resultType':'core'},timeout=20).json()['resultList']['result']
  for p in d: print(p.get('title'),p.get('authorString'),p.get('journalTitle'),p.get('abstractText'))
